<?php declare(strict_types=1);require __DIR__.'/../includes/bootstrap.php';require_student();$uid=(int)current_user()['user_id'];$m=month_start();$s=db()->prepare('SELECT b.*,c.name,COALESCE(SUM(CASE WHEN t.status="active" THEN t.amount ELSE 0 END),0) spent FROM budgets b JOIN categories c ON c.category_id=b.category_id LEFT JOIN transactions t ON t.user_id=b.user_id AND t.category_id=b.category_id AND t.type="expense" AND t.transaction_date>=b.month_start AND t.transaction_date<DATE_ADD(b.month_start,INTERVAL 1 MONTH) WHERE b.user_id=? AND b.month_start=? GROUP BY b.budget_id,c.name ORDER BY c.name');$s->execute([$uid,$m]);$rows=$s->fetchAll();$cats=user_categories($uid,'expense');$pageTitle='Budgets';$activePage='budgets';require __DIR__.'/../includes/app_header.php';?><section class="page-head"><div><span class="eyebrow">PLAN</span><h1>Monthly budgets</h1><p>Set caps and get in-app alerts as you approach them.</p></div></section><div class="two-column"><section class="panel"><div class="panel-head"><div><span class="panel-kicker"><?=e(date('F Y',strtotime($m ?: date('Y-m-01'))))?></span><h2>Create / update</h2></div></div><form class="form" method="post" action="<?=e(url('student/actions/budget-save.php'))?>"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Expense category<select class="input" name="category_id" required><option value="">Choose</option><?php foreach($cats as$c):?><option value="<?=$c['category_id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Monthly limit<input class="input" name="limit_amount" type="number" min="0" step="0.01" required></label><label>Alert threshold %<input class="input" name="alert_threshold_percent" type="number" min="0" max="100" value="80" required></label><button class="btn btn-primary">Save budget</button></form></section><section class="panel"><div class="panel-head"><div><span class="panel-kicker">LIVE MONITOR</span><h2>Budget health</h2></div></div><?php foreach($rows as$b):$pct=$b['limit_amount']>0?((float)$b['spent']/(float)$b['limit_amount'])*100:0;?><div class="budget-block"><div class="row-between"><strong><?=e($b['name'])?></strong><span><?=number_format($pct,0)?>%</span></div><div class="progress <?=$pct>=100?'danger':($pct>=80?'warn':'')?>"><span style="width:<?=min(100,$pct)?>%"></span></div><div class="row-between muted"><span><?=money($b['spent'])?> spent</span><form method="post" action="<?=e(url('student/actions/budget-delete.php'))?>"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="budget_id" value="<?=$b['budget_id']?>"><button class="text-button">Remove</button></form></div></div><?php endforeach;?><?php if(!$rows):?><div class="empty-state">No budgets yet.</div><?php endif;?></section></div><?php require __DIR__.'/../includes/footer.php';?>